import * as C from './core.mjs';
import {initStore,readState,writeState} from './store.mjs';
const $=s=>document.querySelector(s);const app=$('#app');const modalRoot=$('#modal-root');
let state=C.emptyState(),view='home',ready=false,selectedGoal=null,month='',listLimit=20,toastTimer,importData,posterBlob,posterUrl,posterScope='all';
let lastFocus=null,modalDirty=false,saving=false,recordDraftId=null,confirmationActive=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const paths={jar:'M6 8h12M8 5h8v3c0 2 4 3 4 8a8 5 0 0 1-16 0c0-5 4-6 4-8zM10 2l2 3 2-3',home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-7h6v7',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',user:'M20 21a8 8 0 0 0-16 0M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M15 5l-7 7 7 7',close:'M6 6l12 12M6 18 18 6',check:'M5 12l4 4L19 6',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5zM12 14v3',down:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6',up:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',brief:'M3 7h18v14H3zM8 7V3h8v4M3 12h18M10 12v3h4v-3',gift:'M3 9h18v5H3zM5 14v7h14v-7M12 9v12M12 9C1 10 6-1 12 9c6-10 11 1 0 0',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',sad:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M8 9h.01M16 9h.01M8 17q4-5 8 0',file:'M6 2h9l5 5v15H4V2zM14 2v6h6M8 12h8M8 16h8',people:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a7 7 0 0 1 14 0v2M17 4a4 4 0 0 1 0 7M18 15a5 5 0 0 1 4 5',coffee:'M3 8h13v10a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3zM16 8h2a4 4 0 0 1 0 8h-2M6 2v3M11 2v3',dots:'M5 12h.01M12 12h.01M19 12h.01',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2',heart:'M20 4c-4-3-8 2-8 2S8 1 4 4C-3 10 12 22 12 22S27 10 20 4',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7',edit:'M15 3l6 6M4 16 17 3l4 4L8 20l-5 1z',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 10v7M12 6h.01'};
const icon=(n,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.dots}"/></svg>`;
const eventIcon=e=>['sad','file','people','coffee','brief','dots'][C.EVENTS.indexOf(e)]||'dots';
function jarArt(){return `<svg class="jar-art" viewBox="0 0 320 300" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><ellipse cx="160" cy="269" rx="111" ry="13" fill="#d7e2c8"/><ellipse cx="160" cy="272" rx="82" ry="6" fill="#bdcfa8" opacity=".6"/><path d="M160 71c-42-11-54-46-37-42 27 1 35 23 37 42Z" fill="#94bb70" stroke="#254c38" stroke-width="4"/><path d="M160 71c0-34 38-58 47-44 9 13-15 36-47 44Z" fill="#a6c87c" stroke="#254c38" stroke-width="4"/><path d="M111 103c-17 19-46 49-46 91 0 46 32 71 95 71s95-25 95-71c0-42-29-72-46-91Z" fill="#fffef4" stroke="#254c38" stroke-width="4"/><path d="M107 119c-20 29-28 50-28 74 0 35 23 57 51 61" stroke="#d8e9cc" stroke-width="9" stroke-linecap="round"/><path d="M218 125c16 22 24 39 24 58" stroke="#e4edda" stroke-width="6" stroke-linecap="round"/><ellipse cx="160" cy="104" rx="52" ry="11" fill="#c3d9ae" stroke="#254c38" stroke-width="4"/><path d="M109 86v17c0 15 102 15 102 0V86" fill="#eaf2d8"/><ellipse cx="160" cy="86" rx="51" ry="11" fill="#f8f9e8" stroke="#254c38" stroke-width="4"/><path d="M109 86v17c0 15 102 15 102 0V86M132 86h56" stroke="#254c38" stroke-width="4" stroke-linecap="round"/><ellipse cx="126" cy="164" rx="5" ry="7" fill="#254c38"/><ellipse cx="189" cy="164" rx="5" ry="7" fill="#254c38"/><path d="M150 170q9 8 18-1" stroke="#254c38" stroke-width="3.5" stroke-linecap="round"/><ellipse cx="107" cy="179" rx="11" ry="7" fill="#eebd9d" opacity=".65"/><ellipse cx="209" cy="179" rx="11" ry="7" fill="#eebd9d" opacity=".65"/><path d="M161 235c-55-31-35-66-12-47l12 13 12-13c23-19 43 16-12 47Z" fill="#e9a06d" stroke="#254c38" stroke-width="3.5"/><path d="M112 209c12-18 37-3 29 9-5 7-23 10-29-2M209 209c-12-18-37-3-29 9 5 7 23 10 29-2" fill="#fffef4" stroke="#254c38" stroke-width="3.5" stroke-linecap="round"/><path d="M92 250c-15 5-13 15 2 15h20M225 250c15 5 13 15-2 15h-20" fill="#f8f7eb" stroke="#254c38" stroke-width="3.5"/><path d="M49 129l-12-8m233 8 13-8M41 208l-13 4m251-4 13 4" stroke="#dba66f" stroke-width="4" stroke-linecap="round"/><path d="m59 240-6-12m212 14 7-12" stroke="#b5cc96" stroke-width="5" stroke-linecap="round"/></svg>`;}
function brand(){return `<a class="brand" href="#" data-action="brand">${icon('jar',30)}窝囊费<span>WONANG FEE</span></a>`;}
const button=(text,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${text}</button>`;
const current=()=>state.goals.find(g=>g.id===selectedGoal)||C.activeGoal(state);
function nav(){return [['home','jar','我的罐子'],['records','list','所有记录'],['history','history','历史目标'],['settings','user','我的']];}
function render(){if(!ready)return;const g=C.activeGoal(state);if(!g&&!state.goals.length&&view==='home'){app.innerHTML=landing();return;}app.innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<nav>${nav().map(([v,i,t])=>`<button class="nav-item ${view===v?'active':''}" data-action="nav" data-view="${v}">${icon(i)}${t}</button>`).join('')}</nav><div class="sidebar-bottom">${jarArt()}<p>每一笔，都留给未来的自己。</p><p>仅记录计划 · 不自动扣款</p><div class="divider"></div><span>窝囊费 V1.0.1 · 本地体验版</span></div></aside><main class="workspace"><div class="mobile-brand">${brand()}<button class="iconbtn" data-action="nav" data-view="settings" aria-label="设置">${icon('settings')}</button></div>${view==='home'?home():view==='records'?recordList():view==='history'?history():settings()}</main><nav class="bottomnav" aria-label="主导航">${nav().filter(x=>x[0]!=='history').map(([v,i,t])=>`<button class="${view===v?'active':''}" data-action="nav" data-view="${v}">${icon(i,22)}${t}</button>`).join('')}</nav></div>`;}
function landing(){return `<header class="topbar">${brand()}<div class="toplinks"><button data-action="help">它怎么用？</button><button data-action="privacy">数据与隐私</button>${button('开攒我的窝囊费','create')}</div></header><main class="landing"><section class="hero"><div class="hero-copy"><span class="pill"><i></i>打工人的情绪存钱罐</span><h1>这气不能白受，<br><em>窝囊费得攒够。</em></h1><p>被甩锅、改八版、临时加班……<br>把糟心时刻，记成给未来自己的一笔小积累。</p>${button(`开攒我的窝囊费 ${icon('arrow',18)}`,'create')}<div class="hero-fine">${icon('shield',13)}免费开始 · 无需注册 · 无需绑卡</div></div><div class="scene"><div class="bubble">被甩锅一次<br><strong>给自己记 ¥10</strong></div><div class="bubble b2">无效开会<br><strong>给未来留 ¥5</strong></div>${jarArt()}<div class="preview-strip"><div class="row spread"><div><div class="tag">你的小底气，从第一笔开始</div><div class="num">¥ 0.00</div></div><span class="pill">慢慢攒，也算数</span></div><div class="progress" style="margin:12px 0 9px"><i style="width:0%"></i></div><small class="muted">示意页面 · 累计记录金额，不代表账户余额</small></div><div class="hero-note">小小存一笔，日子会好一点。</div></div></section><section class="how" aria-label="使用方法">${[['01','给目标起个名','离职底气、快乐放假，给自己一个盼头。'],['02','发生了，就记一笔','选个场景和小额金额，吐槽写不写都行。'],['03','把委屈，慢慢攒成底气','自主转存、保存战报，按自己的节奏来。']].map(([n,t,p])=>`<div class="how-item"><b>${n}</b><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</section><footer class="landing-footer"><span>仅记录计划，不自动扣款 · 数据保存在此浏览器</span><button data-action="import">恢复备份</button></footer></main>`;}
function head(title,sub='',extra=''){return `<header class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${extra}</header>`;}
function goalCard(g){const t=C.totals(state,g.id);return `<div class="goal-card card">${jarArt()}<div class="goal-main"><div class="row" style="gap:8px">${icon('jar',20)}<h2>${esc(g.name)}</h2></div><div class="big-money"><small>¥</small>${C.money(t.amount)}</div><div class="eyebrow">累计记录${t.amount>=g.target?' · 记录目标已达成':''}</div></div><div class="progress" role="progressbar" aria-label="记录目标进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,t.amount/g.target*100)}"><i style="width:${Math.min(100,t.amount/g.target*100)}%"></i></div><div class="progress-meta"><span>目标 ¥${C.money(g.target)}</span><span>${C.progress(t.amount,g.target)}</span></div>${g.status==='active'?`<button class="goal-menu" data-action="goal-manage" data-id="${g.id}">管理目标 ${icon('arrow',12)}</button>`:''}</div>`;}
function home(){const g=C.activeGoal(state);if(!g)return head('给下一个目标，留点期待','历史的底气还在，新的开始也值得。')+`<div class="card welcome-empty"><div class="empty">${jarArt()}<h3>当前没有进行中的存钱罐</h3><p>归档的记录可以在历史目标里找到。</p>${button('创建新的罐子','create')}</div></div>`;const t=C.totals(state,g.id),entries=C.records(state,g.id);return head('今天的委屈，给自己记上。','慢慢攒，每一笔都在给自己撑腰。',`<time>${C.today().replaceAll('-',' / ')}</time>`)+`<div class="home-grid"><div>${goalCard(g)}<div class="stat-row"><div class="stat"><p>已标记自行转存 ${icon('check',13)}</p><strong>¥ ${C.money(t.transferred)}</strong><small>由你自行确认，不是银行核验</small></div><div class="stat"><p>为自己攒底气</p><strong>${t.count} <span style="font-size:12px;font-weight:400">次</span></strong><small>不用每天记录，按自己的节奏来</small></div></div></div><div class="home-right"><div class="card action-card"><span class="eyebrow">FOR MY FUTURE SELF</span><span class="scribble">↗</span><h2>这一笔，<br>留给未来的自己。</h2><p>无论今天过得怎么样，<br>你都值得被好好对待。</p><div class="quick-events">${['被甩锅','无效开会','临时加班'].map(e=>`<button class="chip" data-action="entry" data-event="${e}">${e}</button>`).join('')}</div>${button(icon('plus',18)+'记一笔窝囊费','entry','orange full')}</div><div class="right-note">${icon('lock',17)} <b>你的吐槽，只留在这里。</b><br>数据仅存在此浏览器，记得定期导出备份。分享战报不会包含具体吐槽。<br><button class="textbtn" data-action="export">备份我的记录</button></div></div></div><section class="journal"><div class="section-head"><h2>最近记录 <span style="font-size:10px;font-weight:400;margin-left:8px;color:#9ba48e">一笔一笔，都算数</span></h2><button class="textbtn" data-action="nav" data-view="records">查看全部 ${icon('arrow',13)}</button></div><div class="card">${entries.length?entries.slice(0,5).map(entryRow).join(''):`<div class="empty">${jarArt()}<h3>第一笔，从今天开始。</h3><p>选一个场景，给自己记一小笔。<br>没有烦心事的日子，也很好。</p></div>`}</div></section><div class="footer-credit">${icon('lock',11)} 当前浏览器本地保存 · 仅记录计划，不自动扣款</div>`;}
function entryRow(e){return `<button class="entry-row" data-action="detail" data-id="${e.id}"><span class="event-icon">${icon(eventIcon(e.event),19)}</span><span class="entry-info"><strong>${esc(e.event)}</strong><p>${e.date.replaceAll('-','.')} ${e.transferred?'<span class="transfer-tag">已标记转存</span>':''}</p></span><span class="entry-amount">+ ¥${C.money(e.amount)}<small>记录金额</small></span>${icon('arrow',14)}</button>`;}
function recordList(){const g=current();if(!g)return head('所有记录','你的第一笔，还在未来。')+`<div class="card empty"><p>先创建一个存钱罐吧。</p>${button('创建目标','create')}</div>`;let entries=C.records(state,g.id).filter(e=>!month||e.date.startsWith(month));const months=[...new Set(C.records(state,g.id).map(e=>e.date.slice(0,7)))];return head(g.status==='archived'?'历史记录':'所有记录',`${esc(g.name)} · 共 ${entries.length} 笔`,g.status==='active'?button(icon('plus',16)+'记一笔','entry','small'):button('历史战报','poster-history','small'))+`<div class="list-filters"><select id="month-filter" aria-label="按月份筛选"><option value="">全部月份</option>${months.map(m=>`<option ${m===month?'selected':''}>${m}</option>`).join('')}</select>${g.status==='archived'?'<span class="pill">已归档 · 只读</span>':''}</div><div class="card panel">${entries.length?entries.slice(0,listLimit).map(entryRow).join(''):`<div class="empty">${jarArt()}<h3>这里还没有记录</h3><p>换个月份看看，或为自己记下第一笔。</p></div>`}${entries.length>listLimit?button('再看20笔','load-more','outline full'):''}</div>`;}
function history(){const archived=state.goals.filter(g=>g.status==='archived').sort((a,b)=>b.archivedAt.localeCompare(a.archivedAt));return head('一路攒下的底气','每一个罐子，都装着你走过的一段日子。',!C.activeGoal(state)?button('新建目标','create','small'):'')+`<div class="panel">${archived.length?archived.map(g=>{const t=C.totals(state,g.id);return `<section class="card archive-item"><div class="row spread"><h2 style="font-size:15px">${esc(g.name)}</h2><span class="pill">已归档</span></div><div class="amount">¥ ${C.money(t.amount)}</div><p class="fine">${t.count} 笔记录 · 目标 ¥${C.money(g.target)} · ${C.progress(t.amount,g.target)}</p><p class="fine">已标记自行转存 ¥${C.money(t.transferred)}</p><div class="modal-actions"><button class="btn secondary small" data-action="history-records" data-id="${g.id}">查看记录</button><button class="btn outline small" data-action="poster" data-id="${g.id}">生成战报</button><button class="iconbtn" data-action="delete-goal" data-id="${g.id}" aria-label="删除归档目标">${icon('trash',16)}</button></div></section>`;}).join(''):`<div class="card empty">${jarArt()}<h3>慢慢攒，不急着毕业。</h3><p>归档后的存钱罐会保存在这里。</p></div>`}</div>`;}
function settingRow(i,t,sub,act){return `<button class="setting-row" data-action="${act}">${icon(i,21)}<div>${t}<small>${sub}</small></div><span class="chev">${icon('arrow',16)}</span></button>`;}
function settings(){return head('我的小底气','把记录照顾好，也把自己照顾好。',`<span class="saved-badge">${icon('shield',14)}仅本机保存</span>`)+`<div class="panel"><section class="card"><div class="row" style="gap:19px"><div style="width:100px">${jarArt()}</div><div><h2 style="font-size:18px">今天，也给自己撑腰。</h2><p class="fine" style="margin-top:9px">无需注册，没有绑卡。<br>你的记录，由你保管。</p></div></div></section><section class="settings-section"><h2>我的记录</h2><div class="card">${settingRow('list','常用事项','添加或移除个人常用事项；不影响历史记录','custom-events')}${settingRow('history','历史目标','查看归档的目标与记录','nav-history')}${settingRow('down','导出完整备份','JSON文件含金额与私密备注，请妥善保管','export')}${settingRow('up','恢复备份','先预览后替换；不会自动合并已有记录','import')}</div></section><section class="settings-section"><h2>使用与隐私</h2><div class="card">${settingRow('info','它怎么用','记录金额、自行转存和目标进度的区别','help')}${settingRow('lock','数据与隐私','仅本地保存，未接入第三方统计','privacy')}${settingRow('file','写一份使用反馈','本地保存草稿，可下载反馈文本；暂未接入客服后台','feedback')}</div></section><section class="settings-section"><h2>数据管理</h2><div class="card">${settingRow('trash','清空此浏览器的数据','不可恢复，建议先导出备份','clear')}</div></section><p class="footer-credit">窝囊费 V1.0.1 · 可体验版本<br>把糟心时刻，变成自己的底气。</p></div>`;}
function showModal(title,body,options={}){lastFocus=document.activeElement;modalDirty=false;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${options.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" data-revision="${state.revision}"><header class="modal-head"><h2 id="modal-title">${title}</h2><button class="iconbtn" data-action="close" aria-label="关闭">${icon('close',21)}</button></header>${body}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>modalRoot.querySelector('[autofocus],input:not([type=checkbox]),button')?.focus());}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';modalDirty=false;if(posterUrl){URL.revokeObjectURL(posterUrl);posterUrl=null;}lastFocus?.isConnected&&lastFocus.focus();}
async function ask(title,text,confirm='确认',danger=false){const previous=modalRoot.firstElementChild,dirty=modalDirty;confirmationActive=true;return new Promise(resolve=>{showModal(title,`<p class="help-copy">${esc(text)}</p><div class="error" role="alert"></div><div class="modal-actions"><button class="btn outline" data-answer="no">再想想</button><button class="btn ${danger?'danger':''}" data-answer="yes">${confirm}</button></div>`);const done=v=>{confirmationActive=false;if(previous){modalRoot.replaceChildren(previous);modalDirty=dirty;previous.querySelector('button,input')?.focus();}else closeModal();resolve(v);};modalRoot.querySelector('[data-answer="yes"]').onclick=()=>done(true);modalRoot.querySelector('[data-answer="no"]').onclick=()=>done(false);modalRoot.querySelector('[data-action="close"]').onclick=e=>{e.stopPropagation();done(false);};});}
async function requestClose(){if(confirmationActive){modalRoot.querySelector('[data-answer="no"]')?.click();return;}if(saving)return;if(modalDirty&&!await ask('放弃这次修改？','未提交的内容不会计入记录。你也可以继续编辑。','放弃修改'))return;try{sessionStorage.removeItem('wonang-entry-draft');}catch{}closeModal();}
function toast(message,undo){clearTimeout(toastTimer);const t=$('#toast');t.innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undo-toast">恢复</button>':''}`;t.classList.add('visible');if(undo)$('#undo-toast').onclick=undo;toastTimer=setTimeout(()=>t.classList.remove('visible'),undo?10000:4200);}
function formError(e){const target=modalRoot.querySelector('.error');if(target)target.textContent=e.message||String(e);else toast(e.message||String(e));}
async function commit(fn,expected){const result=await writeState(expected??state.revision,fn);state=result.state;render();return result.result;}
function targetForm(id){const g=id?state.goals.find(x=>x.id===id):null;if(!g&&C.activeGoal(state)){toast('先归档当前罐子，再创建新目标');return;}showModal(g?'编辑我的目标':'建个窝囊费罐',`<p class="modal-sub">这笔钱，攒来干什么？</p><form id="goal-form" data-id="${g?.id||''}"><div class="option-grid">${C.TYPES.map((t,i)=>`<button type="button" class="option ${g?.type===t||!g&&i===0?'selected':''}" data-choice="goal-type" data-value="${t}">${icon(['brief','sun','gift'][i],24)}${t}</button>`).join('')}</div><input type="hidden" name="type" value="${g?.type||C.TYPES[0]}"><div class="field"><label for="goal-name">给罐子起个名</label><input id="goal-name" name="name" value="${esc(g?.name||'我的离职底气')}" required autocomplete="off"><small>1 至 20 个字</small></div><div class="field"><label for="goal-target">目标金额（元）</label><input class="amount-field" id="goal-target" inputmode="decimal" name="target" value="${g?C.plainMoney(g.target):'1000'}" required></div><div class="field"><label for="goal-default">受一次气，默认记多少？</label><input id="goal-default" name="defaultAmount" inputmode="decimal" value="${g?C.plainMoney(g.defaultAmount):'10'}" required><div class="amount-options">${[5,10,20].map(v=>`<button type="button" class="choice" data-amount="${v}" data-input="goal-default">¥ ${v}</button>`).join('')}<button type="button" class="choice" data-focus="goal-default">自定义</button></div><small>按自己的余力，金额随时可改。</small></div>${!g?`<div class="legal-notice">${icon('lock',14)} 记录仅保存在当前浏览器。清理浏览器或更换设备后不会自动找回，请定期导出备份。<br>仅记录计划，不会扣款或转账。</div>`:''}<div class="error" role="alert"></div><button type="submit" class="btn full">${g?'保存目标':'建好了，开始攒'}</button></form>`);}
function entryForm(event,entryId){const old=entryId?state.entries.find(x=>x.id===entryId):null;const g=old?state.goals.find(x=>x.id===old.goalId):C.activeGoal(state);if(!g){targetForm();return;}if(g.status==='archived'){toast('归档目标为只读');return;}const options=C.eventOptions(state),selected=old?.event||event||C.EVENTS[0],isOneOff=!options.includes(selected),choice=isOneOff?'其他':selected;recordDraftId=old?.id||C.uuid();showModal(old?'编辑这笔窝囊费':'记一笔窝囊费',`<form id="entry-form" data-id="${old?.id||''}" data-goal="${g.id}"><label>今天又遇到什么事了？</label><div class="event-grid">${options.map(e=>`<button type="button" class="option ${choice===e?'selected':''}" data-choice="event" data-value="${esc(e)}">${icon(eventIcon(e),20)}<span>${esc(e)}</span></button>`).join('')}</div><input type="hidden" name="event" value="${esc(choice)}"><div id="custom-event-field" class="field custom-event-field" ${choice==='其他'?'':'hidden'}><label for="entry-custom-event">这次遇到了什么？</label><input id="entry-custom-event" name="customEvent" autocomplete="off" placeholder="例如：下班前临时加需求" value="${esc(isOneOff?selected:'')}"><small>1 至 20 个字；留空则记为“其他”。仅保存在此浏览器。</small><label class="checkbox-inline" style="margin-top:12px"><input type="checkbox" name="rememberCustom" ${isOneOff?'':'checked'}><span>设为常用事项，下次直接选择</span></label></div><div class="field"><label for="entry-amount">给自己攒一笔（元）</label><input class="amount-field" id="entry-amount" name="amount" inputmode="decimal" value="${C.plainMoney(old?.amount||g.defaultAmount)}" required><div class="amount-options">${[5,10,20].map(v=>`<button type="button" class="choice ${v*100===(old?.amount||g.defaultAmount)?'selected':''}" data-amount="${v}" data-input="entry-amount">¥ ${v}</button>`).join('')}<button type="button" class="choice" data-focus="entry-amount">自定义</button></div></div><div class="field"><label for="entry-date">发生日期</label><input id="entry-date" type="date" name="date" min="${C.today(new Date(g.createdAt))}" max="${C.today()}" value="${old?.date||C.today()}" required></div><div class="field"><label for="entry-note">吐槽两句 <span class="muted" style="font-weight:400">（选填）</span></label><textarea id="entry-note" name="note" placeholder="写出来也许会轻松一点。">${esc(old?.note||'')}</textarea><div class="row spread fine" style="margin-top:7px"><span>${icon('lock',12)} 吐槽仅保存在此浏览器，不进入战报</span><span id="note-count">${C.characters(old?.note||'')} / 200</span></div></div><label class="toggle-row"><span>我已自行转存这笔钱</span><input type="checkbox" name="transferred" ${old?.transferred?'checked':''}></label><p class="fine">由你自行确认，本工具不会转账。未勾选时仅记账。</p><div class="error" role="alert"></div><button type="submit" class="btn full" style="margin-top:18px">${old?'保存这笔修改':'记上这笔窝囊费'}</button></form>`);}
function updateCustomField(focus=false){const f=$('#entry-form');if(!f)return;const box=$('#custom-event-field');box.hidden=f.elements.event.value!=='其他';if(!box.hidden&&focus)$('#entry-custom-event').focus();}
function customEventsManager(){const events=C.customEvents(state);showModal('我的常用事项',`<p class="modal-sub">这些事项仅你自己使用，保存在当前浏览器。默认事项仍会保留。</p><form id="custom-events-form"><div class="field"><label for="new-custom-event">添加常用事项</label><input id="new-custom-event" name="eventName" placeholder="例如：下班前临时加需求" autocomplete="off" required><small>1 至 20 个字，最多20个。重复名称会自动合并。</small></div><div class="error" role="alert"></div><button type="submit" class="btn full">添加到常用事项</button></form><div class="divider"></div><div class="section-head"><h3 style="font-size:13px">已保存的事项</h3><span>${events.length} / 20</span></div>${events.length?events.map(v=>`<div class="custom-event-item"><span>${esc(v)}</span><button type="button" class="textbtn" data-action="remove-custom-event" data-value="${esc(v)}" aria-label="移除常用事项：${esc(v)}">移除常用</button></div>`).join(''):'<p class="fine">还没有自定义事项。记一笔时选“其他”，也能添加。</p>'}<p class="fine" style="margin-top:17px">移除常用仅取消快捷选项，不会修改或删除历史记录。备份会包含这些事项。</p>`);}
function saveDraft(){try{const f=$('#entry-form');if(f)sessionStorage.setItem('wonang-entry-draft',JSON.stringify({data:Object.fromEntries(new FormData(f)),time:Date.now(),goalId:f.dataset.goal,entryId:f.dataset.id}));}catch{}}
function readDraft(){try{const d=JSON.parse(sessionStorage.getItem('wonang-entry-draft')||'null');if(d&&Date.now()-d.time<86400000)return d;sessionStorage.removeItem('wonang-entry-draft');}catch{}return null;}
function openEntry(event,id){entryForm(event,id);const f=$('#entry-form'),d=readDraft();if(f&&d&&d.goalId===f.dataset.goal&&(d.entryId||'')===(f.dataset.id||'')){const n=document.createElement('div');n.id='draft-banner';n.className='legal-notice';n.innerHTML='上次还有一笔未提交的草稿。<div class="row"><button type="button" class="textbtn" data-action="draft-restore">恢复草稿</button><button type="button" class="textbtn" data-action="draft-discard">丢弃草稿</button></div>';f.prepend(n);}}
function restoreDraft(){const f=$('#entry-form'),d=readDraft();if(!f||!d)return;for(const key of ['amount','date','note','event','customEvent'])if(typeof d.data[key]==='string')f.elements[key].value=d.data[key];f.elements.transferred.checked=d.data.transferred==='on';f.elements.rememberCustom.checked=d.data.rememberCustom==='on';if(!C.eventOptions(state).includes(f.elements.event.value)){f.elements.customEvent.value=f.elements.event.value;f.elements.event.value='其他';}updateCustomField();f.querySelectorAll('[data-choice="event"]').forEach(n=>n.classList.toggle('selected',n.dataset.value===f.elements.event.value));$('#note-count').textContent=`${C.characters(f.elements.note.value)} / 200`;$('#draft-banner')?.remove();modalDirty=true;toast('草稿已恢复，提交后才会计入记录');}
function success(e){const g=state.goals.find(g=>g.id===e.goalId);showModal('这一笔，给自己撑腰',`<div class="success"><div class="success-check">${icon('check',35)}</div><h2>委屈记下了，<br>底气加一点。</h2><p>窝囊费 + ¥${C.money(e.amount)}</p>${goalCard(g)}<p class="fine">已标记自行转存 ¥${C.money(C.totals(state,g.id).transferred)}</p><p class="fine">今天辛苦了，这笔留给未来的你。</p><button class="btn full" data-action="poster" data-id="${g.id}" data-scope="${e.date===C.today()?'today':'all'}">晒晒我的窝囊费 ${icon('arrow',16)}</button>${button('返回我的罐子','close','outline full')}<button class="textbtn" data-action="delete-entry" data-id="${e.id}">撤销这笔</button></div>`);}
function detail(id){const e=state.entries.find(e=>e.id===id);if(!e){toast('这笔记录已删除');return;}const g=state.goals.find(g=>g.id===e.goalId);showModal('这一笔窝囊费',`<div class="row">${icon(eventIcon(e.event),24)}<h3 style="font-size:17px">${esc(e.event)}</h3><span class="pill" style="margin-left:auto">${g.status==='archived'?'历史只读':e.transferred?'已标记转存':'仅记录'}</span></div><div class="detail-amount">¥ ${C.money(e.amount)}</div><p class="fine">${e.date.replaceAll('-','.')} · ${esc(g.name)}</p>${e.note?`<div class="detail-note">${esc(e.note)}</div><p class="fine" style="margin-top:9px">${icon('lock',12)} 私密吐槽，不会进入分享图片</p>`:'<p class="fine" style="margin-top:15px">这笔没有留下具体吐槽。</p>'}${g.status==='active'?`<label class="toggle-row"><span>我已自行转存这笔钱</span><input type="checkbox" id="detail-transfer" data-id="${e.id}" ${e.transferred?'checked':''}></label><p class="fine">仅由你自行确认，不涉及真实扣款。</p><div class="error" role="alert"></div><div class="modal-actions"><button class="btn secondary" data-action="edit-entry" data-id="${e.id}">${icon('edit',16)}编辑</button><button class="btn danger" data-action="delete-entry" data-id="${e.id}">${icon('trash',16)}删除</button></div>`:'<div class="notice-line">已归档目标中的记录不能编辑。</div>'}`);}
function manageGoal(id){const g=state.goals.find(g=>g.id===id);if(!g)return;showModal('管理我的目标',`<p style="font-size:17px;font-weight:650">${esc(g.name)}</p><p class="fine" style="margin-top:10px">目标 ¥${C.money(g.target)} · ${C.progress(C.totals(state,id).amount,g.target)}</p><div class="divider"></div><button class="setting-row" data-action="edit-goal" data-id="${id}">${icon('edit')}<div>编辑目标<small>修改名称、目标和默认金额</small></div>${icon('arrow',16)}</button><button class="setting-row" data-action="archive" data-id="${id}">${icon('history')}<div>归档这个罐子<small>保留历史记录，然后可以创建下一个目标</small></div>${icon('arrow',16)}</button><button class="setting-row" data-action="poster" data-id="${id}">${icon('gift')}<div>生成我的战报<small>仅分享目标进度，不含具体吐槽</small></div>${icon('arrow',16)}</button><div class="danger-zone"><button class="textbtn" style="color:#a3553b" data-action="delete-goal" data-id="${id}">删除这个目标及全部记录</button></div>`);}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportBackup(){if(!await ask('导出完整备份','备份文件包含你的目标、金额和私密吐槽。请保存在自己信任的位置，不要公开分享。','导出备份'))return;download(new Blob([JSON.stringify(C.backup(state),null,2)],{type:'application/json'}),`窝囊费-备份-${C.today()}.json`);toast('已发起备份下载，请检查浏览器下载记录');}
function importDialog(){importData=null;showModal('恢复我的备份',`<p class="modal-sub">先检查文件，再由你确认。导入会整体替换当前记录，不会自动合并。</p><div class="legal-notice">建议先导出当前备份。支持窝囊费 V1.0 的 JSON 文件，最大5MB。</div><label for="backup-file">选择备份文件</label><input id="backup-file" type="file" accept=".json,application/json"><div id="import-preview" style="margin-top:18px"></div><div class="error" role="alert"></div><button class="btn full" id="import-confirm" data-action="import-confirm" disabled style="margin-top:20px">检查文件后恢复</button>`);}
function help(){showModal('窝囊费怎么用',`<div class="help-copy"><h3>01 给自己定个目标</h3><p>离职底气、快乐放假，或只是奖励自己。目标和每次金额都可以改。</p><h3>02 发生了，就记一小笔</h3><p>选择事件、填金额，吐槽写不写都行。按自己的余力，不用每天打卡。</p><h3>03 自行转存，自己确认</h3><p>“累计记录”是你记下的金额。“已标记转存”是你确认已在自己的账户存好的金额。窝囊费不会扣款、转账、锁定资金或验证银行余额。</p><h3>04 给未来的自己留个战报</h3><p>可以下载图片，也可以隐藏金额和目标名。图片不会包含你的私密吐槽。</p><h3>05 记得备份</h3><p>记录仅保存在此浏览器。换设备、清除数据不会自动找回。前往“我的”导出完整JSON备份，之后可恢复。</p></div>`);}
function privacy(){showModal('数据与隐私',`<div class="help-copy"><p>本体验版本无需账号，不读取支付账单，不接入第三方统计或广告追踪，也不会上传你的目标、金额和吐槽。</p><h3>数据保存在哪里</h3><p>目标、记录保存在当前浏览器的IndexedDB中。浏览器或设备可访问者可能看到记录，本地数据库未额外加密。在线站点的托管服务可能为正常运行保留访问日志，不含你的本地记录内容。</p><h3>分享与备份</h3><p>战报在本机生成，永不包含吐槽。备份JSON包含完整记录和吐槽，未加密，请妥善保管。</p><h3>清除与恢复</h3><p>可删除单笔、删除目标、清空全部数据。清空不可恢复，建议先导出。反馈草稿单独保存在本机，清空全部数据时一并清理。</p><h3>关于体验范围</h3><p>当前没有运营统计、服务端客服、账号或云同步。使用反馈仅能保留草稿和导出，不会假装已提交给运营。</p></div>`);}
function feedback(){let draft='';try{const d=JSON.parse(localStorage.getItem('wonang-feedback')||'null');if(d&&Date.now()-d.time<86400000)draft=d.text;}catch{}showModal('留一份使用反馈',`<p class="modal-sub">客服后台暂未接入。你可以先保存本机草稿，或下载文本交给产品负责人。</p><form id="feedback-form"><div class="field"><label for="feedback-note">哪里不顺手，或想增加什么？</label><textarea id="feedback-note" name="text" placeholder="说说刚才发生的具体情况。" required>${esc(draft)}</textarea><small>最多1000个字；不要填身份证、银行卡或同事联系方式。</small></div><div class="error" role="alert"></div><div class="modal-actions"><button class="btn secondary" type="submit">保存本机草稿</button><button class="btn" type="button" data-action="feedback-download">下载反馈文本</button></div><p class="fine" style="margin-top:15px">草稿24小时后过期。保存草稿不代表已经发送给运营。</p></form>`);}
async function buildPoster(g,hide,scope){const t=C.totals(state,g.id);const dayCount=C.records(state,g.id).filter(e=>e.date===C.today()).length;const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1240;const x=canvas.getContext('2d');x.fillStyle='#faf7ed';x.fillRect(0,0,900,1240);function text(s,px,y,size=30,color='#213f31',weight=500){x.fillStyle=color;x.font=`${weight} ${size}px "Microsoft YaHei", "PingFang SC", sans-serif`;x.fillText(s,px,y);}function round(a,b,c,d,r,fill){x.fillStyle=fill;x.beginPath();x.roundRect(a,b,c,d,r);x.fill();}text('窝囊费',65,100,39,undefined,900);text(g.status==='archived'?'历史目标战报':scope==='today'?'今天这口气，':'这一路的委屈，',65,197,57,undefined,850);text('都攒成了自己的底气。',65,272,57,undefined,850);x.strokeStyle='#e7ac75';x.lineWidth=9;x.beginPath();x.moveTo(70,298);x.lineTo(570,286);x.stroke();const svg=jarArt().replace('class="jar-art"','width="320" height="300"');const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);});x.drawImage(img,230,315,440,410);round(55,730,790,316,28,'#fffef9');text(hide?'正在为自己攒底气':g.name,90,790,27);text(hide?'慢慢攒，也算数。':`¥ ${C.money(t.amount)}`,90,883,hide?43:62,undefined,800);text(hide?'每一笔，都留给未来的自己':'累计记录金额',90,935,23,'#89917e');if(!hide){round(90,963,720,10,5,'#e4e8dd');if(t.amount>0)round(90,963,Math.max(10,720*Math.min(1,t.amount/g.target)),10,5,'#538d5d');text(`目标 ¥${C.money(g.target)} · ${C.progress(t.amount,g.target)}`,90,1013,23,'#89917e');}round(145,1080,610,55,27,'#f6e5d1');text(scope==='today'?`今日为自己攒底气 ${dayCount} 次`:`累计为自己攒底气 ${t.count} 次`,205,1117,25,'#a66c3e');text('情绪存钱打卡 · 非实际账户余额',215,1186,22,'#929887');return new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(Error('图片生成失败')),'image/png'));}
async function poster(id,scope='all'){const g=state.goals.find(g=>g.id===id)||current();if(!g)return;posterScope=g.status==='archived'?'all':scope;showModal('我的窝囊费战报',`<div class="poster-preview"><p class="fine" style="margin-bottom:12px">图片不包含具体吐槽。公开前请检查目标名称。</p><div id="poster-holder"><p class="fine" style="padding:60px;text-align:center">正在生成战报…</p></div></div><div class="poster-controls"><label><input id="poster-hide" type="checkbox" ${state.preferences.hideMoney?'checked':''}>隐藏金额和目标名</label><select id="poster-scope" aria-label="战报范围" style="font-size:11px;padding:8px;width:auto" ${g.status==='archived'?'disabled':''}><option value="all" ${posterScope==='all'?'selected':''}>累计战报</option value="today" ${posterScope==='today'?'selected':''}>今日战报</option></select></div><div class="error" role="alert"></div><button class="btn full" data-action="poster-save" disabled id="poster-save">${icon('down',17)}保存战报图片</button><p class="fine" style="margin-top:12px;text-align:center">手机浏览器若无法下载，可长按图片保存。不会自动发布。</p>`,{wide:true});modalRoot.querySelector('.modal').dataset.goal=g.id;await refreshPoster();}
let posterGeneration=0;
async function refreshPoster(){const token=++posterGeneration;const id=modalRoot.querySelector('.modal')?.dataset.goal;const g=state.goals.find(x=>x.id===id);if(!g)return;const hide=$('#poster-hide').checked,scope=$('#poster-scope').value;$('#poster-save').disabled=true;try{const b=await buildPoster(g,hide,scope);if(token!==posterGeneration||!$('#poster-holder'))return;if(posterUrl)URL.revokeObjectURL(posterUrl);posterBlob=b;posterUrl=URL.createObjectURL(b);$('#poster-holder').innerHTML=`<img class="poster-image" src="${posterUrl}" alt="窝囊费${hide?'隐私':''}战报，不包含具体吐槽">`;$('#poster-save').disabled=false;}catch(e){formError(e);}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action],[data-choice],[data-amount],[data-focus]');if(!el)return;if(el.tagName==='A')ev.preventDefault();if(el.disabled)return;if(el.dataset.focus){$('#'+el.dataset.focus)?.focus();return;}if(el.dataset.amount){const input=$('#'+el.dataset.input);input.value=el.dataset.amount;input.dispatchEvent(new Event('input',{bubbles:true}));el.parentElement.querySelectorAll('.choice').forEach(n=>n.classList.toggle('selected',n===el));return;}if(el.dataset.choice){const name=el.dataset.choice==='goal-type'?'type':'event';el.closest('form').elements[name].value=el.dataset.value;el.parentElement.querySelectorAll('.option').forEach(n=>n.classList.toggle('selected',n===el));if(name==='event')updateCustomField(true);if(name==='type'&&!$('#goal-form').dataset.id)$('#goal-name').value='我的'+el.dataset.value;modalDirty=true;saveDraft();return;}const act=el.dataset.action;try{if(act==='custom-events')return customEventsManager();if(act==='remove-custom-event'){await commit(s=>C.removeCustomEvent(s,el.dataset.value));customEventsManager();toast('已从常用事项移除，历史记录保持原样');return;}if(act==='brand'){if(modalRoot.children.length)await requestClose();else{view='home';selectedGoal=null;render();}return;}if(act==='nav'||act==='nav-history'){view=act==='nav-history'?'history':el.dataset.view;selectedGoal=null;month='';closeModal();render();window.scrollTo(0,0);return;}if(act==='draft-restore')return restoreDraft();if(act==='draft-discard'){sessionStorage.removeItem('wonang-entry-draft');$('#draft-banner')?.remove();return;}if(act==='create')return targetForm();if(act==='close')return requestClose();if(act==='entry')return openEntry(el.dataset.event);if(act==='detail')return detail(el.dataset.id);if(act==='edit-entry')return openEntry(null,el.dataset.id);if(act==='goal-manage')return manageGoal(el.dataset.id);if(act==='edit-goal')return targetForm(el.dataset.id);if(act==='help')return help();if(act==='privacy')return privacy();if(act==='feedback')return feedback();if(act==='export')return exportBackup();if(act==='import')return importDialog();if(act==='load-more'){listLimit+=20;render();return;}if(act==='history-records'){selectedGoal=el.dataset.id;view='records';month='';render();return;}if(act==='poster'||act==='poster-history')return poster(el.dataset.id||current()?.id,el.dataset.scope);if(act==='poster-save'){download(posterBlob,`窝囊费-战报-${C.today()}.png`);toast('已发起图片下载；手机也可长按战报保存');return;}if(act==='archive'){const id=el.dataset.id;if(!await ask('归档这个罐子？','归档后历史保留且不可修改，不能取消归档。之后可以创建新目标。删除恢复窗口中的记录也将永久删除。','确认归档'))return;await commit(s=>C.archiveGoal(s,id));closeModal();view='history';render();toast('这份底气，已经好好收起来了');return;}if(act==='delete-goal'){const id=el.dataset.id;if(!await ask('删除目标及全部记录？','此操作不可恢复。建议先在“我的”导出完整备份，归档则能保留历史。','删除目标',true))return;await commit(s=>C.removeGoal(s,id));closeModal();selectedGoal=null;view='home';render();toast('目标和关联记录已删除');return;}if(act==='delete-entry'){const id=el.dataset.id;if(!await ask('撤销这笔记录？','累计记录与已标记转存金额会同步减少。删除后10秒内可恢复。','撤销这笔'))return;const deleted=await commit(s=>C.deleteEntry(s,id));closeModal();if(deleted)toast('这笔记录已撤销，10秒内可恢复',async()=>{try{await commit(s=>C.restoreEntry(s,id));toast('已恢复这笔记录');}catch(e){toast(e.message);}});return;}if(act==='import-confirm'){if(!importData)return;if(!await ask('用备份替换当前数据？',`将恢复 ${importData.goals.length} 个目标、${importData.entries.length} 条记录。当前数据会被整体替换，不可撤销，请先备份。`,'确认恢复',true))return;await commit(s=>{const rev=s.revision;Object.assign(s,structuredClone(importData));s.revision=rev;});closeModal();view='home';selectedGoal=null;render();toast('备份已恢复，历史数据未算作新记录');return;}if(act==='clear'){if(!await ask('清空本机全部数据？','将删除所有目标、记录和反馈草稿，不可恢复。请先导出备份。','清空全部',true))return;await commit(s=>{const rev=s.revision;Object.assign(s,C.emptyState());s.revision=rev;});try{localStorage.removeItem('wonang-feedback');sessionStorage.removeItem('wonang-entry-draft');}catch{}closeModal();view='home';selectedGoal=null;render();toast('本机数据已清空');return;}if(act==='feedback-download'){const text=$('#feedback-note').value.trim();if(!text||C.characters(text)>1000)throw Error('请填写1至1000字的反馈');download(new Blob([`窝囊费 V1.0 使用反馈\n日期：${C.today()}\n\n${text}\n\n此文件由用户导出，尚未发送。`],{type:'text/plain;charset=utf-8'}),`窝囊费-反馈-${C.today()}.txt`);toast('已发起反馈文本下载，尚未发送给运营');return;}}catch(e){formError(e);}});
document.addEventListener('submit',async ev=>{const form=ev.target;if(!['goal-form','entry-form','feedback-form','custom-events-form'].includes(form.id))return;ev.preventDefault();if(saving)return;const data=Object.fromEntries(new FormData(form));const expected=Number(form.closest('.modal').dataset.revision);try{saving=true;form.querySelector('[type=submit]').disabled=true;if(form.id==='goal-form'){if(form.dataset.id){const g=state.goals.find(x=>x.id===form.dataset.id);const newTarget=C.cents(data.target,100,100000000);if(newTarget<C.totals(state,g.id).amount&&newTarget!==g.target&&!await ask('调整后将显示已达标',`新目标为 ¥${C.money(newTarget)}，历史记录金额不会改变。`,'保存新目标'))return;await commit(s=>C.editGoal(s,form.dataset.id,data),expected);closeModal();toast('目标已更新，历史金额保持不变');}else{await commit(s=>C.createGoal(s,data),expected);view='home';selectedGoal=null;closeModal();render();toast('罐子建好了，第一笔从你决定的那刻开始');}}else if(form.id==='entry-form'){data.transferred=form.elements.transferred.checked;data.rememberCustom=form.elements.rememberCustom.checked;const old=state.entries.find(x=>x.id===form.dataset.id);if(old?.transferred&&data.transferred&&C.cents(data.amount)!==old.amount){data.transferred=await ask('这笔新金额也已自行转存？','如果还没存好新的金额，选择“再想想”会保留记录修改并取消转存标记。','确认已转存');}const e=await commit(s=>C.saveEntry(s,{...data,id:form.dataset.id||recordDraftId,isNew:!form.dataset.id,goalId:form.dataset.goal}),expected);modalDirty=false;try{sessionStorage.removeItem('wonang-entry-draft');}catch{}if(old){detail(e.id);toast(data.transferred?'修改已保存':'修改已保存，转存状态以当前勾选为准');}else success(e);}else if(form.id==='custom-events-form'){await commit(s=>C.addCustomEvent(s,data.eventName),expected);customEventsManager();toast('已添加常用事项，下次记一笔可直接选择');}else{const text=data.text.trim();if(!text||C.characters(text)>1000)throw Error('请填写1至1000字的反馈');localStorage.setItem('wonang-feedback',JSON.stringify({text,time:Date.now()}));modalDirty=false;toast('反馈草稿已保存本机，尚未发送');}}catch(e){formError(e);if(e.message.includes('另一个页面')){state=await readState();render();}}finally{saving=false;if(form.isConnected)form.querySelector('[type=submit]').disabled=false;}});
document.addEventListener('input',ev=>{if(ev.target.closest('form'))modalDirty=true;if(ev.target.id==='entry-note')$('#note-count').textContent=`${C.characters(ev.target.value)} / 200`;if(ev.target.closest('#entry-form'))saveDraft();});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='month-filter'){month=el.value;listLimit=20;render();}if(el.id==='detail-transfer'){const expected=Number(el.closest('.modal').dataset.revision);await commit(s=>C.toggleTransfer(s,el.dataset.id,el.checked),expected);detail(el.dataset.id);toast(el.checked?'已标记由你自行转存':'已取消转存标记，累计记录未变');}if(el.closest('#entry-form'))saveDraft();if(el.id==='poster-hide'||el.id==='poster-scope')await refreshPoster();if(el.id==='backup-file'){importData=null;$('#import-confirm').disabled=true;const file=el.files?.[0];if(!file)return;if(file.size>5*1024*1024)throw Error('文件超过5MB，请选择完整JSON备份');let parsed;try{parsed=JSON.parse(await file.text());}catch{throw Error('无法解析，请选择窝囊费导出的JSON备份');}importData=C.validateBackup(parsed);const preview=$('#import-preview');preview.innerHTML=`<div class="file-preview">${icon('check',18)} 备份检查通过<br>目标 ${importData.goals.length} 个 · 记录 ${importData.entries.length} 条<br>恢复将覆盖当前记录，请确认已备份。</div>`;$('#import-confirm').disabled=false;$('#import-confirm').textContent='用此备份恢复数据';}}catch(e){formError(e);if(el.id==='detail-transfer')el.checked=!el.checked;}});
document.addEventListener('keydown',ev=>{if(!modalRoot.children.length)return;if(ev.key==='Escape'){ev.preventDefault();requestClose();}if(ev.key==='Tab'){const nodes=[...modalRoot.querySelectorAll('button:not(:disabled),input:not([type=hidden]),textarea,select,a[href]')].filter(n=>n.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
async function start(){try{state=await initStore(async()=>{state=await readState();render();if(modalRoot.children.length)toast('另一个页面更新了数据，当前表单保存时将检查冲突');});if(state.schema!==1)throw Error('当前数据版本不支持，请使用同版本应用打开');ready=true;render();}catch(e){app.innerHTML=`<main class="landing" style="padding-top:70px;max-width:650px">${brand()}<h1 style="font-size:27px;margin:35px 0 18px">暂时打不开你的存钱罐。</h1><p class="help-copy">${esc(e.message)}<br>请使用正常浏览模式并允许此网站使用本地存储。我们不会假装记录已保存。</p><button class="btn" style="margin-top:24px" id="retry-start">重新尝试</button></main>`;$('#retry-start').onclick=()=>location.reload();}}
start();
